PRAGMA foreign_keys=ON;
CREATE TABLE meta_ingest_run(ingest_run_id INTEGER PRIMARY KEY,builder_version TEXT,schema_version TEXT,started_at TEXT,finished_at TEXT,status TEXT,raw_records INTEGER,normalized_records INTEGER,duplicate_records INTEGER,anomaly_records INTEGER);
CREATE TABLE meta_archive(archive_id INTEGER PRIMARY KEY,ingest_run_id INTEGER,source_kind TEXT,archive_name TEXT,year INTEGER,sha256 TEXT,size_bytes INTEGER,imported_at TEXT);
CREATE TABLE meta_source_file(source_file_id INTEGER PRIMARY KEY,archive_id INTEGER,source_kind TEXT,filename TEXT,business_date TEXT,record_count INTEGER,sha256 TEXT,record_length INTEGER,is_canonical INTEGER NOT NULL DEFAULT 1,source_role TEXT NOT NULL DEFAULT 'CANONICAL',imported_at TEXT);
CREATE TABLE meta_anomaly(anomaly_id INTEGER PRIMARY KEY,ingest_run_id INTEGER,severity TEXT,anomaly_type TEXT,source_kind TEXT,business_date TEXT,source_file_id INTEGER,record_no INTEGER,business_key TEXT,detail_json TEXT,detected_at TEXT);
CREATE TABLE meta_duplicate(duplicate_id INTEGER PRIMARY KEY,ingest_run_id INTEGER,source_kind TEXT,business_key TEXT,first_source_file_id INTEGER,first_record_no INTEGER,first_record_hash TEXT,second_source_file_id INTEGER,second_record_no INTEGER,second_record_hash TEXT,is_identical INTEGER,resolution TEXT,resolution_reason TEXT,diff_json TEXT,selected_source_file_id INTEGER,selected_record_no INTEGER,detected_at TEXT);
CREATE TABLE race(race_key TEXT PRIMARY KEY,race_date TEXT,venue_code TEXT,year INTEGER,race_no INTEGER,distance INTEGER,track_type TEXT,condition_code TEXT,grade_code TEXT,race_name TEXT,source_origin TEXT,source_file_id INTEGER,source_record_no INTEGER,record_hash TEXT);
CREATE TABLE entry(race_key TEXT,horse_no INTEGER,horse_id TEXT,horse_name TEXT,jockey_name TEXT,running_style TEXT,distance_aptitude TEXT,uptrend TEXT,source_file_id INTEGER,source_record_no INTEGER,record_hash TEXT,PRIMARY KEY(race_key,horse_no));
CREATE TABLE result(race_key TEXT,horse_no INTEGER,horse_id TEXT,horse_name TEXT,finish INTEGER,abnormal_code TEXT,final_win_odds REAL,final_win_popularity INTEGER,final_place_odds_lower REAL,odds_10am_win REAL,odds_10am_place REAL,win_payout INTEGER,place_payout INTEGER,source_file_id INTEGER,source_record_no INTEGER,record_hash TEXT,PRIMARY KEY(race_key,horse_no));
CREATE TABLE training_analysis(race_key TEXT,horse_no INTEGER,training_index REAL,source_file_id INTEGER,source_record_no INTEGER,record_hash TEXT,PRIMARY KEY(race_key,horse_no));
CREATE TABLE workout(race_key TEXT,horse_no INTEGER,workout_seq INTEGER,training_date TEXT,course_code TEXT,chase_state TEXT,source_file_id INTEGER,source_record_no INTEGER,record_hash TEXT,PRIMARY KEY(race_key,horse_no,workout_seq));
CREATE TABLE result_extension(race_key TEXT,horse_no INTEGER,special_note_code_1 TEXT,special_note_code_2 TEXT,race_comment TEXT,source_file_id INTEGER,source_record_no INTEGER,record_hash TEXT,PRIMARY KEY(race_key,horse_no));
CREATE TABLE entry_previous_result(race_key TEXT,horse_no INTEGER,sequence INTEGER,prev_result_key TEXT,prev_race_key TEXT,source_file_id INTEGER,source_record_no INTEGER,PRIMARY KEY(race_key,horse_no,sequence));
CREATE TABLE horse_current(horse_id TEXT PRIMARY KEY,horse_name TEXT,sex TEXT,record_hash TEXT,source_file_id INTEGER,source_record_no INTEGER,valid_from TEXT);
CREATE TABLE horse_history(history_id INTEGER PRIMARY KEY,horse_id TEXT,valid_from TEXT,valid_to TEXT,record_hash TEXT,source_file_id INTEGER,source_record_no INTEGER);
CREATE TABLE code_master_version(version_id INTEGER PRIMARY KEY,source_name TEXT,imported_at TEXT);
CREATE TABLE code_master(code_type TEXT,code TEXT,label TEXT,version_id INTEGER,PRIMARY KEY(code_type,code));
CREATE INDEX ix_src_date ON meta_source_file(source_kind,business_date); CREATE INDEX ix_race_year ON race(year); CREATE INDEX ix_entry_horse ON entry(horse_id);
CREATE VIEW v_race_readable AS SELECT r.*,g.label grade_label FROM race r LEFT JOIN code_master g ON g.code_type='GRADE' AND g.code=r.grade_code;
CREATE VIEW v_entry_readable AS SELECT e.*,s.label running_style_label FROM entry e LEFT JOIN code_master s ON s.code_type='RUNNING_STYLE' AND s.code=e.running_style;
CREATE VIEW v_workout_readable AS SELECT w.*,c.label course_label FROM workout w LEFT JOIN code_master c ON c.code_type='TRAINING_COURSE' AND c.code=w.course_code;
CREATE VIEW v_result_extension_readable AS SELECT * FROM result_extension;
